export function getProductSpecTranslation(productRaw, locale = 'en') {
  if (!productRaw) return undefined;
  if (locale === 'en') return productRaw.specs;
  const localized = SUPPLEMENTAL_SPECS[locale]?.[productRaw.slug];
  if (!localized) return undefined;
  const original = SOURCE_SPECS[productRaw.slug];
  if (Object.keys(original).length !== Object.keys(productRaw.specs || {}).length ||
      Object.entries(original).some(([key, value]) => productRaw.specs?.[key] !== value)) {
    throw new Error('Regenerate localized specifications after changing product specs: ' + productRaw.slug);
  }
  return localized;
}
